javas.java:

int def powerDeviationPercent(int:total, int:baseline) {
    return (total - baseline) * 100 / baseline;
}


str def efficiencyLevel(int:total, int:output, int:standardPerUnit) {
    int standardTotal = output * standardPerUnit;
    if (total * 100 > standardTotal * 120) {
        return "WASTE";
    } else if (total * 100 > standardTotal * 105) {
        return "ATTENTION";
    } else {
        return "NORMAL";
    }
}


int def demandExcessPercent(int:maxDemand, int:contract) {
    return (maxDemand - contract) * 100 / contract;
}


int def waterDeviationPercent(int:usage, int:baseline) {
    return (usage - baseline) * 100 / baseline;
}


boolean def temperatureAbnormal(boolean:controlled, int:temperature) {
    if (controlled) {
        if (temperature >= 18) {
            if (temperature <= 26) {
                return false;
            } else {
                return true;
            }
        } else {
            return true;
        }
    } else {
        return false;
    }
}
